arguments.file_text:
namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings == 0 ? 0 : (double)RatingSum / TotalRatings;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 50
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated pecorino and pepper.", "Toss hot pasta with pancetta off the heat.", "Pour egg mixture over pasta and toss quickly.", "Serve immediately with extra cheese."],
                TotalRatings = 8, RatingSum = 35
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken thighs", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer.", "Stir in cream and garam masala.", "Add chicken and simmer 10 minutes."],
                TotalRatings = 15, RatingSum = 68
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Samosas", Category = "Indian",
                Description = "Crispy pastry pockets filled with spiced potatoes and peas.",
                Ingredients = ["Potatoes", "Peas", "Cumin seeds", "Coriander", "Pastry dough", "Oil for frying"],
                Steps = ["Boil and mash potatoes.", "Cook peas and mix with potatoes and spices.", "Cut dough into circles and fill with mixture.", "Fold into triangles and seal edges.", "Deep fry until golden brown.", "Serve with mint chutney."],
                TotalRatings = 6, RatingSum = 25
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crunchy taco shells with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer.", "Warm taco shells in the oven.", "Fill shells with seasoned beef.", "Top with lettuce, tomato, cheese, and sour cream.", "Serve with salsa and lime wedges."],
                TotalRatings = 10, RatingSum = 42
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and zesty avocado dip, perfect as a side or appetizer.",
                Ingredients = ["Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Salt"],
                Steps = ["Halve and pit avocados, scoop into a bowl.", "Mash to desired consistency.", "Dice onion, cilantro, and jalapeño.", "Mix everything together.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
                TotalRatings = 20, RatingSum = 90
            },
            new Recipe
            {
                Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
                Description = "Classic chewy cookies loaded with chocolate chips.",
                Ingredients = ["Butter", "Sugar", "Brown sugar", "Eggs", "Vanilla", "Flour", "Baking soda", "Chocolate chips"],
                Steps = ["Cream butter with both sugars.", "Beat in eggs and vanilla.", "Mix flour, baking soda, and salt, then combine.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheets.", "Bake at 375°F for 9-11 minutes."],
                TotalRatings = 25, RatingSum = 118
            },
            new Recipe
            {
                Id = 8, Title = "Crème Brûlée", Category = "Desserts",
                Description = "Silky vanilla custard with a caramelized sugar crust.",
                Ingredients = ["Heavy cream", "Egg yolks", "Sugar", "Vanilla bean"],
                Steps = ["Heat cream with vanilla until simmering.", "Whisk yolks with sugar.", "Temper yolks with hot cream.", "Pour into ramekins and bake in water bath at 325°F.", "Chill for at least 4 hours.", "Sprinkle sugar on top and torch until caramelized."],
                TotalRatings = 9, RatingSum = 41
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="star-btn @(star <= _selectedRating ? "filled" : "")"
                @onclick="() => Rate(star)"
                disabled="@_hasRated"
                title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= _selectedRating ? "★" : "☆")
        </button>
    }
    <span class="rating-info">
        @if (_hasRated)
        {
            <span class="rating-thanks">Thanks for rating!</span>
        }
        @if (Recipe is not null && Recipe.TotalRatings > 0)
        {
            <span>@Recipe.AverageRating.ToString("0.0") avg (@Recipe.TotalRatings ratings)</span>
        }
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

