toolArgs.file_text:
@rendermode InteractiveServer
@using RecipeShare.Services

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="star-btn @(star <= _selectedRating ? "filled" : "")"
                @onclick="() => Rate(star)"
                disabled="@_hasRated"
                title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= _selectedRating ? "★" : "☆")
        </button>
    }
    <span class="rating-info">
        @if (_hasRated)
        {
            <span class="rating-thanks">Thanks for rating!</span>
        }
        @if (Recipe is not null && Recipe.TotalRatings > 0)
        {
            <span>@Recipe.AverageRating.ToString("0.0") avg (@Recipe.TotalRatings ratings)</span>
        }
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    [Inject]
    private RecipeService RecipeService { get; set; } = default!;

    private Models.Recipe? Recipe { get; set; }

    private int _selectedRating;
    private bool _hasRated;

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(RecipeId);
    }

    private void Rate(int stars)
    {
        if (_hasRated) return;
        _selectedRating = stars;
        _hasRated = true;
        RecipeService.AddRating(RecipeId, stars);
        Recipe = RecipeService.GetById(RecipeId);
    }
}

