.star-rating {
    display: flex;
    align-items: center;
    gap: 0.15rem;
    margin: 1rem 0;
}

.star-btn {
    background: none;
    border: none;
    font-size: 1.8rem;
    cursor: pointer;
    color: #ccc;
    padding: 0 2px;
    transition: color 0.15s, transform 0.15s;
    line-height: 1;
}

.star-btn:hover:not(:disabled) {
    transform: scale(1.2);
}

.star-btn.filled {
    color: #f5a623;
}

.star-btn:disabled {
    cursor: default;
}

.rating-info {
    margin-left: 0.75rem;
    font-size: 0.9rem;
    color: #666;
}

.rating-thanks {
    color: #28a745;
    font-weight: 500;
    margin-right: 0.5rem;
}

